const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const agudo = ee.Geometry.Point([-53.24, -29.65]);
  const aoi = agudo.buffer(5000); // 5 km radius

  const date1 = '2023-11-05';
  const date2 = '2023-11-21';

  // 2. Data Acquisition & Check
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBit = 1 << 10;
    const cirrusBit = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBit).eq(0)
                   .and(qa.bitwiseAnd(cirrusBit).eq(0));
    return image.updateMask(mask);
  }

  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    return image.addBands(ndwi);
  }

  // Get images for both dates
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date1, ee.Date(date1).advance(3, 'day'))
    .map(maskClouds)
    .map(addNDWI);

  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(date2, ee.Date(date2).advance(3, 'day'))
    .map(maskClouds)
    .map(addNDWI);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Nov 5 images: ${size1}, Nov 21 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('No images found for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get median composite and extract water
  const img1 = col1.median();
  const img2 = col2.median();

  const water1 = img1.select('NDWI').gt(0);
  const water2 = img2.select('NDWI').gt(0);

  // 4. Calculate water areas with pixel counting
  const count1 = await water1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2 = await water2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels - Nov 5: ${count1}, Nov 21: ${count2}`);
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  const area1 = await water1.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const area2 = await water2.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  // 5. Validation & Final Answer
  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  const area1_km2 = area1 / 1e6;
  const area2_km2 = area2 / 1e6;

  console.log(`Nov 5, 2023 water area: ${area1_km2.toFixed(2)} km2 (Pixels: ${count1})`);
  console.log(`Nov 21, 2023 water area: ${area2_km2.toFixed(2)} km2 (Pixels: ${count2})`);
  console.log(`Change: ${(area2_km2 - area1_km2).toFixed(2)} km2`);

  if (area2 > area1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
